/**
 * Extract and validate chat message from webhook
 * 
 * Expected format:
 * {
 *   "message": "What are your office hours?",
 *   "sessionId": "session_abc123",
 *   "userName": "John" (optional)
 * }
 */

const webhookData = $input.first().json;

// Extract message
const userMessage = webhookData.message || webhookData.query || webhookData.text || "";
const sessionId = webhookData.sessionId || webhookData.session_id || `session_${Date.now()}`;
const userName = webhookData.userName || webhookData.user_name || "there";

// Validate message
if (!userMessage || userMessage.trim() === "") {
  return [{
    json: {
      error: true,
      response: "I didn't receive a message. Please ask me a question about Dr. Jennifer's clinic!",
      sessionId: sessionId
    }
  }];
}

// Check for common greetings
const greetings = ["hi", "hello", "hey", "good morning", "good afternoon", "good evening"];
const messageLower = userMessage.toLowerCase().trim();
const isGreeting = greetings.some(greeting => messageLower === greeting || messageLower.startsWith(greeting + " "));

console.log(`
💬 Chat Message Received:
  - Session: ${sessionId}
  - User: ${userName}
  - Message: ${userMessage}
  - Is Greeting: ${isGreeting}
`);

return [{
  json: {
    userMessage: userMessage,
    sessionId: sessionId,
    userName: userName,
    isGreeting: isGreeting,
    timestamp: new Date().toISOString(),
    error: false
  }
}];

/**
 * Format AI response for chatbot display
 * Add helpful quick action buttons
 */

const chatResponse = $input.first().json;
const userMessage = $('Parse Chat Message').item.json.userMessage;
const messageLower = userMessage.toLowerCase();

// Extract response text
let responseText = chatResponse.output || chatResponse.text || chatResponse.response || "I apologize, but I couldn't generate a response. Please try again or call our office at (555) 123-4567.";

// Determine quick action buttons based on context
const quickActions = [];

// Appointment-related keywords
if (messageLower.includes("appoint") || messageLower.includes("schedule") || messageLower.includes("book")) {
  quickActions.push({
    label: "📅 Book Appointment",
    url: "https://cal.com/izzydevbuilds/appointment-with-dr.-jennifer",
    type: "link"
  });
}

// Hours/contact keywords
if (messageLower.includes("hour") || messageLower.includes("open") || messageLower.includes("call") || messageLower.includes("contact")) {
  quickActions.push({
    label: "📞 Call Office",
    action: "tel:5551234567",
    type: "phone"
  });
}

// Prescription keywords
if (messageLower.includes("prescription") || messageLower.includes("refill") || messageLower.includes("medication")) {
  quickActions.push({
    label: "💊 Request Refill (Portal)",
    url: "https://www.drjenniferclinic.com/portal",
    type: "link"
  });
}

// Insurance/billing keywords
if (messageLower.includes("insurance") || messageLower.includes("billing") || messageLower.includes("payment") || messageLower.includes("cost")) {
  quickActions.push({
    label: "💳 Billing Questions",
    action: "tel:5551234567,3",
    type: "phone"
  });
}

// Lab results keywords
if (messageLower.includes("lab") || messageLower.includes("result") || messageLower.includes("test")) {
  quickActions.push({
    label: "🔬 View Lab Results",
    url: "https://www.drjenniferclinic.com/portal",
    type: "link"
  });
}

// Emergency keywords
if (messageLower.includes("emergency") || messageLower.includes("urgent") || messageLower.includes("after hours")) {
  quickActions.push({
    label: "🚨 After-Hours Nurse",
    action: "tel:5551234599",
    type: "phone"
  });
}

// Default actions if none matched
if (quickActions.length === 0) {
  quickActions.push(
    {
      label: "📅 Book Appointment",
      url: "https://cal.com/izzydevbuilds/appointment-with-dr.-jennifer",
      type: "link"
    },
    {
      label: "📞 Call Office",
      action: "tel:5551234567",
      type: "phone"
    }
  );
}

console.log(`
✅ AI Response Generated:
  - Length: ${responseText.length} characters
  - Quick Actions: ${quickActions.length}
`);

return [{
  json: {
    response: responseText,
    quickActions: quickActions.slice(0, 3), // Max 3 buttons
    timestamp: new Date().toISOString(),
    sessionId: $('Parse Chat Message').item.json.sessionId,
    userName: $('Parse Chat Message').item.json.userName
  }
}];

