/**
 * Log chat interaction to Google Sheet for analytics
 * Track: timestamp, user message, AI response, session ID
 */

const userMessage = $('Parse Chat Message').item.json.userMessage;
const aiResponse = $input.first().json.response;
const sessionId = $input.first().json.sessionId;
const userName = $input.first().json.userName;

return [{
  json: {
    Timestamp: new Date().toISOString(),
    Session_ID: sessionId,
    User_Name: userName,
    User_Message: userMessage,
    AI_Response: aiResponse.substring(0, 500), // Truncate for sheet
    Message_Length: userMessage.length,
    Response_Length: aiResponse.length,
    Quick_Actions_Count: $input.first().json.quickActions?.length || 0
  }
}];
